window.ScripturaLexicons.THAYER.rowsHtml+="<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0233\" data-source=\"THAYER\" data-search=\"ἀλήθεια substantivo feminino, -ας verdade objetiva; doutrina verdadeira; sinceridade Jo 8.32; 14.6; 17.17; 18.38; Rm 1.18,25; 2.2; 3.7; 15.8; 1Co 5.8; Gl 2.5,14; Ef 4.21,25; 1Jo 1.6; 3Jo 3 Thayer pp. 26–27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλήθεια</td><td>substantivo feminino, -ας</td><td>verdade objetiva; doutrina verdadeira; sinceridade</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0234\" data-source=\"THAYER\" data-search=\"ἀληθεύω verbo em -εύω dizer a verdade; professar a verdade Gl 4.16; Ef 4.15 Thayer pp. 26–27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθεύω</td><td>verbo em -εύω</td><td>dizer a verdade; professar a verdade</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0235\" data-source=\"THAYER\" data-search=\"ἀληθής adjetivo, -ές verdadeiro; não falso; fidedigno; veraz Jo 5.31–32; 8.13–17; 19.35; 21.24; Fp 4.8; Tt 1.13; 2Pe 2.22; Mt 22.16; Mc 12.14; Rm 3.4 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθής</td><td>adjetivo, -ές</td><td>verdadeiro; não falso; fidedigno; veraz</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0236\" data-source=\"THAYER\" data-search=\"ἀληθινός adjetivo, -ή, -όν real; genuíno; plenamente correspondente ao nome; verdadeiro Jo 1.9; 4.23; 6.32; 15.1; 17.3; Hb 8.2; 9.24; 1Ts 1.9; 1Jo 5.20; Ap 3.7,14 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθινός</td><td>adjetivo, -ή, -όν</td><td>real; genuíno; plenamente correspondente ao nome; verdadeiro</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0237\" data-source=\"THAYER\" data-search=\"ἀλήθω verbo em -θω moer grãos Mt 24.41; Lc 17.35 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλήθω</td><td>verbo em -θω</td><td>moer grãos</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0238\" data-source=\"THAYER\" data-search=\"ἀληθῶς advérbio verdadeiramente; de fato; certamente Jo 1.47; 4.42; 6.14; 7.26,40; 17.8; Mt 14.33; 26.73; Lc 21.3; At 12.11; 1Ts 2.13 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀληθῶς</td><td>advérbio</td><td>verdadeiramente; de fato; certamente</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0239\" data-source=\"THAYER\" data-search=\"ἁλιεύς substantivo masculino, -έως pescador Mt 4.18–19; Mc 1.16–17; Lc 5.2 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλιεύς</td><td>substantivo masculino, -έως</td><td>pescador</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0240\" data-source=\"THAYER\" data-search=\"ἁλιεύω verbo em -εύω pescar Jo 21.3 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλιεύω</td><td>verbo em -εύω</td><td>pescar</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0241\" data-source=\"THAYER\" data-search=\"ἁλίζω verbo em -ίζω; futuro passivo ἁλισθήσομαι salgar; temperar com sal; purificar por prova Mt 5.13; Mc 9.49 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλίζω</td><td>verbo em -ίζω; futuro passivo ἁλισθήσομαι</td><td>salgar; temperar com sal; purificar por prova</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0242\" data-source=\"THAYER\" data-search=\"ἀλίσγημα substantivo neutro, -ατος contaminação; poluição ritual At 15.20 Thayer pp. 27\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλίσγημα</td><td>substantivo neutro, -ατος</td><td>contaminação; poluição ritual</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0243\" data-source=\"THAYER\" data-search=\"ἀλλά partícula adversativa mas; porém; contudo; ao contrário; antes; exceto Mt 24.6; Jo 16.7; Rm 5.14; 1Co 1.17; 9.2; 15.10; 2Co 4.16; Gl 2.3; Fp 2.27 Thayer pp. 27–28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλά</td><td>partícula adversativa</td><td>mas; porém; contudo; ao contrário; antes; exceto</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0244\" data-source=\"THAYER\" data-search=\"ἀλλάσσω verbo em -σσω trocar; mudar; substituir; transformar At 6.14; Rm 1.23; Gl 4.20; 1Co 15.51–52; Hb 1.12 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλάσσω</td><td>verbo em -σσω</td><td>trocar; mudar; substituir; transformar</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0245\" data-source=\"THAYER\" data-search=\"ἀλλαχόθεν advérbio por outro lugar; de outra direção Jo 10.1 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλαχόθεν</td><td>advérbio</td><td>por outro lugar; de outra direção</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0246\" data-source=\"THAYER\" data-search=\"ἀλλαχοῦ advérbio em outro lugar; alhures Mc 1.38 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλαχοῦ</td><td>advérbio</td><td>em outro lugar; alhures</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0247\" data-source=\"THAYER\" data-search=\"ἀλληγορέω verbo em -έω falar alegoricamente; interpretar figuradamente Gl 4.24 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλληγορέω</td><td>verbo em -έω</td><td>falar alegoricamente; interpretar figuradamente</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0248\" data-source=\"THAYER\" data-search=\"ἁλληλουϊά interjeição hebraica transcrita; indeclinável aleluia! louvai ao Senhor! Ap 19.1,3–4,6 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλληλουϊά</td><td>interjeição hebraica transcrita; indeclinável</td><td>aleluia! louvai ao Senhor!</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0249\" data-source=\"THAYER\" data-search=\"ἀλλήλων pronome recíproco; apenas casos oblíquos uns aos outros; mutuamente Mt 24.10; Jo 13.35; At 28.25; Rm 1.12; Tg 5.16; Ap 6.4 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλήλων</td><td>pronome recíproco; apenas casos oblíquos</td><td>uns aos outros; mutuamente</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-thayer-0250\" data-source=\"THAYER\" data-search=\"ἀλλογενής adjetivo de duas terminações, -ές estrangeiro; de outra raça ou nação Lc 17.18 Thayer pp. 28\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλογενής</td><td>adjetivo de duas terminações, -ές</td><td>estrangeiro; de outra raça ou nação</td><td><span class=\"source-pill\">THAYER</span></td></tr>\n";
window.ScripturaLexicons.THAYER.cardsHtml+="<article id=\"entry-thayer-0233\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"26–27\" data-thayer-pdf-leaf=\"50\" data-thayer-column=\"direita (26); esquerda (27)\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθεια\" data-meanings=\"verdade objetiva; doutrina verdadeira; sinceridade\">ἀλήθεια</h1><div class=\"entry-meta\">substantivo feminino, -ας · Thayer, p. 26–27, direita (26); esquerda (27)</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλήθεια, -ας, ἡ, derivado de ἀληθής: verdade. I. Objetivamente. 1. Aquilo que é verdadeiro na matéria considerada, em oposição ao inventado, imaginário e falso: Tiago 3.14; João 8.45–46; 16.7; Romanos 9.1; 1Timóteo 2.7. Dizer a verdade, testemunhar segundo a realidade dos fatos (João 5.33); «toda a verdade» em Marcos 5.33. Expressões ἐν ἀληθείᾳ, «na verdade, realmente» (Mateus 22.16; João 4.23–24); ἐπ’ ἀληθείας, «de fato» (Marcos 12.14,32; Lucas 20.21); κατ’ ἀλήθειαν, «conforme a realidade, com imparcialidade» (Romanos 2.2).</p><p class=\"entry-text\">2. Em assuntos religiosos, «verdade» designa o que é verdadeiro a respeito de Deus, de seus propósitos e dos deveres humanos. (a) Em amplitude filosófica, a pergunta cética τί ἐστιν ἀλήθεια, «que é a verdade?» (João 18.38). (b) Conhecimento verdadeiro de Deus acessível pela razão (Romanos 1.18,25) e a verdade que a Lei mosaica procura transmitir (Romanos 2.20).</p><p class=\"entry-text\">(c) De modo especial, verdade proclamada pelo cristianismo sobre Deus e sobre o cumprimento de seus propósitos por Cristo, contrastada com superstições, falsas doutrinas e conduta contrária à fé: ἡ ἀλήθεια τοῦ εὐαγγελίου, «verdade do Evangelho» (Gálatas 2.5,14); ὁ λόγος τῆς ἀληθείας (Colossenses 1.5; Efésios 1.13; 2Timóteo 2.15; Tiago 1.18); πνεῦμα τῆς ἀληθείας (João 14.17; 15.26; 16.13; 1João 4.6); ἐγώ εἰμι ἡ ἀλήθεια, «eu sou a verdade» (João 14.6); ἁγίασον ... ἐν τῇ ἀληθείᾳ, «santifica-os na verdade» (João 17.17). A verdade também deve ser praticada na vida (João 3.21; 1João 1.6; 2João 4; 3João 3–4), e pode ser objeto de resistência ou desvio (Romanos 2.8; Tiago 5.19).</p><p class=\"entry-text\">II. Subjetivamente, excelência pessoal: franqueza de espírito livre de simulação, hipocrisia e engano; sinceridade e integridade de caráter harmonizadas com a verdade divina: João 8.44; 1Coríntios 5.8; 13.6; Efésios 4.21; 5.9; 6.14; 3João 3; 2João 1. Referido a Deus, pode designar sua fidelidade em manter as promessas (Romanos 15.8), e Thayer discute Romanos 3.7. A palavra, conforme o autor, não aparece no Apocalipse, nem em 1Tessalonicenses, Filemom e Judas. Referências bibliográficas a Hölemann e Wendt.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Jo 8.32; 14.6; 17.17; 18.38; Rm 1.18,25; 2.2; 3.7; 15.8; 1Co 5.8; Gl 2.5,14; Ef 4.21,25; 1Jo 1.6; 3Jo 3</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 26–27, folhas PDF 50–51, coluna direita (26); esquerda (27). OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dAnPera, -as, 4}, (dAnOns), [fr. Hom. down], verity, truth. \nI. objectively; 1. univ. what is true in any matter \nunder consideration (opp. to what is feigned, fictitious, \nfalse): Jas. ili. 14; ddnderav A€yeuy, epeiv, Jn. vill. 45 sq.; \nxvi. 7; Ro. ix. 1; 1 Co. xii. 6; 1 Tim. ii. 7; etmev atta \nmacav tiv adnOeay, everything as it really was, Mk. v. \n33, (so in classics); paptupetv ty adnOeia to testify ac￾cording to the true state of the case, Jn. v. 33; ina \nbroader sense, Aadeiv adnevav to speak always according \nto truth, Eph. iv. 25; [aAndelas pnuara amopbéyyouat, as \nopp. to the vagaries of madness, Acts xxvi. 25]; adj@eca \néyévero, was shown to be true by the event, 2 Co. vii. 14. \név adnOcia in truth, truly, as the case is, according to \nfact: Mt. xxii. 16; Jn. iv. 23 sq. (as accords with the \ndivine nature); 2 Co. vii. 14; Col. i 6; ém ddnéelas \na. truly, in truth, according to truth: Mk. xii. 32; Lk. \niv. 25, (Job ix. 2 Sept.; Philo, vit. Moys.i.§ 1). b. of \na truth, in reality, in fact, certainly: Mk. xii. 14; Lk. \nxx. 21; [xxii. 59]; Acts iv. 27; x. 34, (Clem. Rom. 1Cor. 23, 5 and 47, 8); [cf. W. § 51, 2f.; B. 336 (289)]; \nkar’ G\\nevay in accordance with fact, i. e. (ace. to the \ncontext) justly, without partiality: Ro. ii. 2; etre mpo￾gacet, cire addneia, Phil. i. 18; ev &amp;pyo k. adnbeia, \n1 Jn. iii, 18 [Rec. om. év; so Eph. iv. 21 WH mrg.]. \n2. In reference to religion, the word denotes what is true in things appertaining to God and the duties of man, (‘moral and religious truth’); and that a. with the greatest latitude, in the sceptical question ri éorw aAn￾Odea, Jn. xviii. 38; b. the true notions of God which are open to human reason without his supernatural in- tervention: Ro. i. 18; also 7 dAjOeca Oeod the truth of \nwhich God is the author, Ro. i. 25, cf. 19, (1 dd#Oeva rod \nXpiorov, Evang. Nicod. c. 5, 2; accordingly it is not, as many interpret the phrase, the true nature of God Lyet \nHesych. d\\eupa kupios ta Tov \n(Hadt., Xen., Plat., Jo￾26 arnGevw \nsee Mey. ad loc.]); truth, the embodiment of which the \nJews sought in the Mosaic law, Ro. ii. 20. c. the truth, \nas taught in the Christian religion, respecting God and \nthe execution of his purposes through Christ, and respect￾ing the duties of man, opposed alike to the superstitions \nof the Gentiles and the inventions of the Jews, and \nto the corrupt opinions and precepts of false teachers \neven among Christians: 7 dAnOea rov evayy. the truth \nwhich is the gospel or which the gospel presents, Gal. ii. \n5, 14, [cef. W. § 34, 3 a.]; and absol. 9 dAnOea and \ndAnOeva: Jn. i. 14,17; viii. 32, 40; [xvi 13]; xvii. 19; \n1 Jn i 85.4, 212 Jno Galoaitata(huce.) canvents \n2 Co. iy...2)5 xis 8) Eph iy 24002) Leite Oy slee sal \nTim. ii. 7 (€v miore: x. ddnOeia in faith and truth, of \nwhich I became a partaker through faith) ; iii. 15; iv. \n35 vi. 52 2 Tim. i. 18% i. 8s iv.4e) Wit. 14502 ees. \ni. 12; [3 Jn. 8,12]; 6 Adyos rHs adnOeias, Col. i.5; Eph. \ni. 13; 2 Tim. ii. 15; Adyos ddnOeias, 2 Co. vi. 7; Jas. i. \n18; dd0s THs ad. 2 Pet. ii. 2; amiatis adnOeias, 2 Th. ii. \n13 [W. 186 (175)]; taxon ths ad. 1 Pet. i. 22; émliyrva￾ots ths GA. Heb. x. 26; 1° Pim. ii. 4; 2 Dima. 25); ai. \n7; (Tit. i. 1]; avedpa tis ad. the Spirit (of God) which \nis truth (1 Jn. v. 6) and imbues men with the knowledge \nof the truth, Jn. xiv.17; [xvi. 13]; xv. 26; 1 Jn. iv. 6; \neyo eiut 7 adAnGeca I am he in whom the truth is summed \nup and impersonated, Jn. xiv. 6; 7 dd7nOeud cov [ Rec. ] \n(i. e. Oeov) the truth which is in thee and proceeds from \nthee, Jn. xvii. 17; [€rrw adAnOeva Xpiorod év poi i. e. \ncontrols, actuates, me, 2 Co. xi. 10]; etvas ex ris adnbeias \nto be eager to know the truth, Jn. xviii. 37 (see éx, II. 7, \nand eipi,V. 3 d.); to proceed from the truth, 1 Jn. ii. 21; \nto be prompted and controlled by the truth, 1 Jn.iii. 19; \npaptupety TH adnO. to give testimony in favor of the \ntruth in order to establish its authority among men, Jn. \nXVill. 37; adnOecav roreitvy to exemplify truth in the life, \nto express the form of truth in one’s habits of thought \nand modes of living, Jn. iii. 21; 1 Jn. i. 6, (Tob. xiii. 6; \niv. 6; cf. Neh. ix. 33; 6ddv dAnOelas aipetiCecOa, Ps. \nexvill. (cxix.) 30); so also mepumareiv év rp ad. 2 Jn. 4; \n3 Jn. 3 sq.; drebeiv rf dd. is just the opposite, Ro. ii. 8; \nso also mAavnOjvat awd ths ad. Jas. v. 19. II. sub￾jectively; truth as a personal excellence; that candor of mind which is free from affectation, pretence, simula- tion, falsehood, deceit: Jn. yiii. 44; sincerity of mind and integrity of character, or a mode of life in harmony with divine truth: 1 Co. v. 8; xiii. 6 (opp. to ddcia) ; Eph. iv. 21 [see I. 1 b. above]; v. 9; [vi. 14]; cod 9 ad7Gea the truth as it is discerned in thee, thy habit of thinking and acting in congruity with truth, 3 Jn. 3; 7) GAnOea tod Geod which belongs to God, i. e. his holi- ness [but cf. mepuroeto, 1 b. fin.], Ro. iii. 7; spec. ve- racity (of God in keeping his promises), Ro. xv. 8; év aAnéeia sincerely and truthfully, 2 Jn. 1; 3Jn.1. The word is not found in Rev. ({nor in 1 Thess., Philem., Jude]). Cf. Hélemann, “ Bibelstudien ”, (Lpz. 1859) Ite Abth. p. 8 sqq.; [ Wendt in Stud. u. Krit., 1883, p. 511 sqq.]*</p></section></article>\n<article id=\"entry-thayer-0234\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"26–27\" data-thayer-pdf-leaf=\"50\" data-thayer-column=\"direita (26); esquerda (27)\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθεύω\" data-meanings=\"dizer a verdade; professar a verdade\">ἀληθεύω</h1><div class=\"entry-meta\">verbo em -εύω · Thayer, p. 26–27, direita (26); esquerda (27)</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀληθεύω, derivado de ἀληθής: dizer a verdade. (a) Ensinar o que é verdadeiro, Gálatas 4.16; (b) professar a doutrina verdadeira, Efésios 4.15. Thayer registra que a margem da versão inglesa revista prefere em ambas «proceder verdadeiramente» (*to deal truly*), ressaltando que a palavra pode expressar ação e não só fala. Há paralelos em Ésquilo, Xenofonte, Platão e Aristóteles.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Gl 4.16; Ef 4.15</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 26–27, folhas PDF 50–51, coluna direita (26); esquerda (27). OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">aAnbevw ; in prof. writ. ([Aeschyl.], Xen., Plat., Aristot., al.) to speak the truth; a. to teach the truth: ri\n[continuação p. 27]\nGal. iv. 16. b. to profess the truth (true doctrine) : Eph. iv. 15. [R. V. mrg. in both pass. to deal truly.]*</p></section></article>\n<article id=\"entry-thayer-0235\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθής\" data-meanings=\"verdadeiro; não falso; fidedigno; veraz\">ἀληθής</h1><div class=\"entry-meta\">adjetivo, -ές · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀληθής, -ές, de ἀ- privativo e raiz relacionada a λανθάνω, segundo etimologia transmitida: aquilo que não está oculto, verdadeiro, autêntico. 1. Verdadeiro, conforme os fatos, oposto a mera aparência ou invenção (João 4.18; 19.35; 1João 2.8,27; Atos 12.9; Filipenses 4.8); testemunho fidedigno (João 5.31–32; 8.13,17; 21.24; 3João 12), julgamento justo (João 8.16 com variante crítica), provérbio verdadeiro (2Pedro 2.22), graça que se pode confiar (1Pedro 5.12).</p><p class=\"entry-text\">2. Aquele que ama ou diz a verdade, veraz, digno de confiança (Mateus 22.16; Marcos 12.14; João 7.18; 2Coríntios 6.8); de Deus (João 3.33; 8.26; Romanos 3.4). 3. Em certos contextos equivale a ἀληθινός no sentido de verdadeiro em oposição ao que não merece o nome (João 6.55 nas edições críticas). A nota de distinção é remetida ao artigo seguinte e a Trench §8 e Schmidt.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Jo 5.31–32; 8.13–17; 19.35; 21.24; Fp 4.8; Tt 1.13; 2Pe 2.22; Mt 22.16; Mc 12.14; Rm 3.4</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">adnbfs, -és, (a priv. and A7jOe, Aabeiv [AavOdve], 7d \nAnos, — cf. duabys; lit. not hidden, unconcealed), [fr. \nHom. down]; Avirues Jn. dv.wlS3ex541);&#39; xix. 35% \n1 Jn. ii. 8, 27; Acts xii. 9 (an actual occurrence, opp. \nto épapa); Phil. iv. 8; paprupia, Jn. v. 31 sq.; viii. \n13 sq. 17; xxi. 24; 3 Jn. 12; Tit. i. 13; xpious, just, \nJn. viii. 16 (LT Tr WH dann); mapomia, 2 Pet. ii. \n22; xdpts, grace which can be trusted, 1 Pet. v. 12. \n2. loving the truth, speaking the truth, truthful: Mt. xxii. \n16; Mk. xii. 14; Jn. vii. 18; 2 Co. vi. 8 (opp. to \nmavos); of God, In. iii. 33; viii. 26; Ro. iii. 4 (opp. to \nWevorns). 3. i. q. aAnO@vds, 1: Jn. vi. 55 (L T Tr \nWH; for Rec. ddnOas), as in Sap. xii. 27, where dAnOis \nGeds is contrasted with ots éddxouv Oeovs. Cf. Riickert, \nAbendmahl, p. 266 sq. [On the distinction betw. this \nword and the next, see Trench § viii. ; Schmidt ch. 178, 6.]*</p></section></article>\n<article id=\"entry-thayer-0236\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθινός\" data-meanings=\"real; genuíno; plenamente correspondente ao nome; verdadeiro\">ἀληθινός</h1><div class=\"entry-meta\">adjetivo, -ή, -όν · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀληθινός, -ή, -όν, segundo Thayer frequente em João, usado desde Platão. 1. Aquele que possui, não só o nome ou aparência, mas a natureza real correspondente ao nome: genuíno, verdadeiro. (a) Oposto ao fictício, falsificado ou fingido: Deus verdadeiro (1Tessalonicenses 1.9; João 17.3; 1João 5.20). (b) Realidade em contraste com representação ou figura: tabernáculo verdadeiro (Hebreus 8.2), santuário real ou celestial (Hebreus 9.24).</p><p class=\"entry-text\">(c) Perfeito ou digno do nome por excelência, em contraste com o defeituoso, frágil ou incerto: verdadeiros adoradores (João 4.23); luz verdadeira (João 1.9; 1João 2.8); pão verdadeiro (João 6.32); videira verdadeira (João 15.1); Cristo como o Verdadeiro (Apocalipse 3.7); testemunha fiel e verdadeira (Apocalipse 3.14). Substantivado, τὸ ἀληθινόν, o bem real, superior às riquezas externas (Lucas 16.11). 2. Em alguns contextos, sincero, veraz, digno de confiança (Hebreus 10.22; Apocalipse 21.5; 22.6). A distinção com ἀληθής é discutida por Trench, Tittmann e Donaldson.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Jo 1.9; 4.23; 6.32; 15.1; 17.3; Hb 8.2; 9.24; 1Ts 1.9; 1Jo 5.20; Ap 3.7,14</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">GAnPivds, -7, -ov, (freq. in prof. writ. fr. Plato down; \n[twenty-three times in Jn.’s writ.; only five (acc. to \nLchm. six) times in the rest of the N.T.]); 1. “that \nwhich has not only the name and semblance, but the real \nnature corresponding to the name” (Tittmann p. 155; \n[‘‘ particularly applied to express that which is all that it \npretends to be, for instance, pure gold as opp. to adul￾terated metal” Donaldson, New Crat. § 258; see, at \nlength, Trench § viii.]), in every respect corresponding to \nthe idea signified by the name, real and true, genuine; \na. opp. to what is fictitious, counterfeit, imaginary, \nsimulated, pretended: 6eds (TDN TORN, 2) Che xv.1 3); \n1 Th. i. 9; Heb. ix. 14 Lehm.; Jn. xvii. 3; 1 Jn. v. 20. \n(adn Owoi pirat, Dem. Phil. 3, p. 113, 27.) b. it con￾trasts realities with their semblances: oxnvn, Heb. viii. \n2; the sanctuary, Heb. ix. 24. (6 tmros contrasted \nwith 6 év Ti eixdm, Ael. v. h. 2, 3.) c. opp. to what is \nimperfect, defective, frail, uncertain: Jn. iv. 23, 37; vii. \n28; used without adjunct of Jesus as the true Messiah, \nRev. iii. 7; pas, Jn. i. 9; 1 In. ii. 8; kpiows, Jn. vill. 16 \n(L T Tr WH;; Is. lix. 4); xpioess, Rev. xvi. 7; xix. 2; \npros, as nourishing the soul unto life everlasting, Jn. \nvi. 32; duredos, Jn. xv. 1; paprvpia, Jn. xix. 35; pdprus, \nRey. iii. 14; Seomdrns, Rev. vi. 10; 680%, Rev. xv. 3; \ncoupled with mords, Rev. iii. 14; xix. 11; substantively, \n7d dAnOwdv the genuine, real good, opp. to external \nriches, Lk. xvi. 11, ([ois pev yap ddnOwds mdovros ev \novpav@, Philo de praem. et poen. § 17, p. 425 ed. \nMang.; cf. Wetst. on Lk. 1. c.]; d6Anrai, Polyb. 1, 6, 6). \n2. i. 4. ddnOns, true, veracious, sincere, (often so in Sept.) : \nxapdia, Heb. x. 22 (per? adnOeias ?v xapdia arnOiv7, Is. \nXxxvili. 3); Adyor, Rev. [xix. 9]; xxi. 5; xxii. 6, (Plut. \napoph. p. 184 e.). [Cf. Cremer 4te Aufl. s. v. dhjOea. ] *</p></section></article>\n<article id=\"entry-thayer-0237\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλήθω\" data-meanings=\"moer grãos\">ἀλήθω</h1><div class=\"entry-meta\">verbo em -θω · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλήθω, forma comum do grego em lugar do ático ἀλέω: moer, especialmente grãos em moinho. Mateus 24.41; Lucas 17.35. Thayer menciona o costume de mulheres e escravas girarem as mós manuais (Êxodo 11.5; Homero, *Odisseia* 20.105), remetendo a Lobeck e aos dicionários bíblicos.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 24.41; Lc 17.35</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dd40w; (a com. Grk. form for the Attic ddéa, cf. Lob. \nad Phryn. p. 151); to grind: Mt. xxiv. 41; Lk. xvii. \n35. It was the custom to send women and female slaves \nto the mill-houses [?] to turn the hand-mills (Ex. xi. 5), \nwho were called by the Greeks yuvaixes dderpides (Hom. \nOd. 20, 105); [cf. B. D. s. v. Mill].*</p></section></article>\n<article id=\"entry-thayer-0238\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀληθῶς\" data-meanings=\"verdadeiramente; de fato; certamente\">ἀληθῶς</h1><div class=\"entry-meta\">advérbio · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀληθῶς, advérbio de ἀληθής: verdadeiramente, de fato, realmente, certamente. Exemplos em João 1.47; 4.42; 6.14; 7.26,40; 17.8; Mateus 14.33; 26.73; 27.54; Lucas 21.3; Atos 12.11; 1Tessalonicenses 2.13; 1João. Empregado desde Ésquilo.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Jo 1.47; 4.42; 6.14; 7.26,40; 17.8; Mt 14.33; 26.73; Lc 21.3; At 12.11; 1Ts 2.13</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">ddAnOds, adv., [fr. Aeschyl. down], truly, of a truth, in \n27 anrXa \nreality; most certainly: Jn. i. 47 (48) ; iv. 42; vi. 14, 05 \nRec. ; vii. 26, 40; viii. 31; xvii. 8; Mt. xiv. 33; xxvi. \n73; (Mk. xiv. 70; Mt.] xxvii. 54; [Mk. xv. 39]; Lk. \nix. 27; xii. 44; xxi. 3; Acts xii. 11; 1 Th.ii.13; 1 Jn. 1s Gs</p></section></article>\n<article id=\"entry-thayer-0239\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλιεύς\" data-meanings=\"pescador\">ἁλιεύς</h1><div class=\"entry-meta\">substantivo masculino, -έως · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἁλιεύς, -έως, ὁ, de ἅλς, ἁλός («mar»): pescador. Mateus 4.18–19; Marcos 1.16–17; Lucas 5.2. Thayer assinala que Tischendorf e Westcott–Hort apresentam em todas as passagens a forma ἁλεεύς, à qual remete a entrada entre colchetes anterior. Não confundir alternância de grafia com acepção diversa.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 4.18–19; Mc 1.16–17; Lc 5.2</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">ddtevs, -€ws, 5, (Gs, adds, the sea), [fr. Hom. down]; \na fisherman, fisher: Mt. iv. 18 sq.; Mk. i. 16 sq.; Lk. \nv. 2, —in all which pass. T and WH have dneeis fr. the \nform dXeevs, q. v.*</p></section></article>\n<article id=\"entry-thayer-0240\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλιεύω\" data-meanings=\"pescar\">ἁλιεύω</h1><div class=\"entry-meta\">verbo em -εύω · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἁλιεύω, de ἁλιεύς: pescar; João 21.3. Atestado em Fílon e Plutarco.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Jo 21.3</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">Gebw; (dduevs) ; to fish: Jn. xxi. 3. [Philo, Plut.]*</p></section></article>\n<article id=\"entry-thayer-0241\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλίζω\" data-meanings=\"salgar; temperar com sal; purificar por prova\">ἁλίζω</h1><div class=\"entry-meta\">verbo em -ίζω; futuro passivo ἁλισθήσομαι · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἁλίζω, de ἅλας, «sal»: salgar, temperar ou polvilhar com sal. No Novo Testamento aparece apenas no futuro passivo. Mateus 5.13: «por que meio lhe será devolgado o sabor?», acerca do sal que perde sua força.</p><p class=\"entry-text\">Marcos 9.49: nas variantes textuais, «todo sacrifício será salgado com sal» (cf. Levítico 2.13; Ezequiel 43.24); a expressão «todo um será salgado com fogo» é interpretada por Thayer como aperfeiçoamento do cristão pelas aflições e provas, que purificam e fortalecem a alma. O lexicógrafo ressalva ser passagem muito difícil e reconhece outras explicações, com remissão a Meyer.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 5.13; Mc 9.49</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dritw: (GAs, adds, salt); to salt, season with salt, sprin￾kle with salt; only the fut. pass. is found in the N. T.: \nev tim dducOnoerat; by what means can its saltness be \nrestored? Mt. v.13; @voia adi ddicOjoerat, the sacrifice \nis sprinkled with salt and thus rendered acceptable to \nGod, Mk. ix. 49 [R GL Tr txt. br.], (Lev. ii. 13; Ezek. \nxliii. 24; Joseph. antt. 3, 9, 1; cf. Knobel on Lev. \np- 369 sq.; Win. RWB. s. v. Salz; [BB.DD. s. v. Salt]); \nmas mupt dduoOnoera, every true Christian is rendered \nripe for a holy and happy association with God in his \nkingdom by fire, i. e. by the pain of afflictions and \ntrials, which if endured with constancy tend to purge \nand strengthen the soul, Mk. ix. 49. But this ex￾tremely difficult passage is explained differently by \nothers ; [cf. Meyer, who also briefly reviews the history \nof its exposition]. (Used by the Sept., Aristot., [cf. \nSoph. Lex.|; Ignat. ad Magnes. 10 [shorter form] d\\i￾oOnre ev Xpiota, iva pry SiapOapy tis ev vuiv.) [Comp.: \novv-adi¢@, — but see the word. |*</p></section></article>\n<article id=\"entry-thayer-0242\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλίσγημα\" data-meanings=\"contaminação; poluição ritual\">ἀλίσγημα</h1><div class=\"entry-meta\">substantivo neutro, -ατος · Thayer, p. 27, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλίσγημα, -ατος, τό, de ἀλισγέω, forma rara vinculada à ideia de macular: impureza, contaminação. Em Atos 15.20, a impureza decorrente de alimentos deixados de sacrifícios pagãos (cf. v. 29). Thayer afirma não conhecer exemplos profanos do substantivo ou do verbo correlato, mas compara Eclesiástico, Daniel e Malaquias.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">At 15.20</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27, folhas PDF 51, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dAiocynpa, -ros, Td, (dAvoyew to pollute, which occurs \nSir. xl. 29; Dan.i.8; Mal. i. 7,12; akin to diva, ddwéo \nto besmear [ Lat. linere, cf. Lob. Pathol. Element. p. 21; \nRhemat. p. 123; Steph., Hesych., Sturz, De Dial. Alex. \np- 145]), pollution, contamination: Acts xv. 20 (rod \ndméxerOar xtX. to beware of pollution from the use \nof meats left from the heathen sacrifices, cf. vs. 29). \nNeither ddvoyéw nor ddtoynpa occurs in Grk. writ.*</p></section></article>\n<article id=\"entry-thayer-0243\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"27–28\" data-thayer-pdf-leaf=\"51\" data-thayer-column=\"direita (27); esquerda (28)\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"mas; porém; contudo; ao contrário; antes; exceto\">ἀλλά</h1><div class=\"entry-meta\">partícula adversativa · Thayer, p. 27–28, direita (27); esquerda (28)</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλλά, partícula adversativa originada, segundo Thayer, de ἄλλα, neutro plural de ἄλλος: propriamente «outras coisas além daquelas mencionadas». Difere de δέ na força opositiva; comparar o latim *at* ou *sed* e *autem*.</p><p class=\"entry-text\">I. «Mas, porém». Após concessão ou afirmação anterior: «não obstante, apesar disso» (Mateus 24.6; Marcos 13.20; João 16.7,20; Romanos 5.14); introduz objeção (João 7.27; Romanos 10.18), exceção (Lucas 22.53; Romanos 4.2), restrição (João 11.42; Gálatas 4.8), ou gradação ascendente «antes, pelo contrário, e até» (João 16.2; 2Coríntios 1.9), frequentemente com καί. ἀλλ’ οὐδέ, «mas nem sequer» (Lucas 23.15; Atos 19.2; 1Coríntios 3.2, com variantes).</p><p class=\"entry-text\">Pode marcar a passagem à questão principal, sobretudo antes de imperativos (Mateus 9.18; Marcos 9.22; Lucas 7.7), ou apresentar oração elíptica com ἵνα (Marcos 14.49). No início de apódose depois de καὶ εἰ, εἰ καί, εἰ, ἐάν ou εἴπερ, pode significar «contudo, ainda assim», com referências específicas em 2Coríntios 4.16; 5.16; Colossenses 2.5; 1Coríntios 9.2; 4.15; 8.6. Pode seguir μέν em contraste.</p><p class=\"entry-text\">Combinações: ἀλλά γε, «contudo ao menos», «ainda assim certamente» (1Coríntios 9.2; Lucas 24.21); ἀλλ’ ἤ, «senão, exceto» (1Coríntios 3.5, com ressalvas críticas; Lucas 12.51; 2Coríntios 1.13); ἀλλ’ οὐ, «mas não» (Hebreus 3.16, com alternativa de pontuação), e ἀλλ’ οὐχί, «não será antes?» (Lucas 17.8).</p><p class=\"entry-text\">II. Depois de uma negação, estabelece oposição «não ... mas», semelhante a *sed* latino: Marcos 5.39; João 7.16; 1Coríntios 1.17; 7.10,19; 2Coríntios 7.9. Em «não ... mas» a força pode ser retórica, correspondendo a «não tanto ... quanto» (Mateus 10.20; João 12.44; Atos 5.4; 1Coríntios 15.10). οὐ μόνον ... ἀλλὰ καί, «não somente ... mas também», com ou sem καί (João 5.18; 11.52; Romanos 1.32; Atos 19.26).</p><p class=\"entry-text\">Em certos contextos a negação anterior é elíptica e deve ser suprida (Mateus 11.7–9; Lucas 7.24–26; Atos 19.2; Gálatas 2.3; 2Coríntios 7.11); ἀλλ’ ἵνα pode seguir uma negação implícita (João 1.8; 9.3; Marcos 4.22). A nota final de Thayer discute a elisão de -α em ἀλλά perante vogais e a frequência das grafias manuscritas, citando Scrivener, Gregory, Tischendorf, Westcott–Hort e gramáticas de Winer e Buttmann.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 24.6; Jo 16.7; Rm 5.14; 1Co 1.17; 9.2; 15.10; 2Co 4.16; Gl 2.3; Fp 2.27</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 27–28, folhas PDF 51–52, coluna direita (27); esquerda (28). OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">d\\Ad, an adversative particle, derived from @AXa, \nneut. of the adj. dAdos, which was originally pronounced \naddés (cf. Klotz ad Devar. ii. p. 1 sq.), hence properly, \nother things sc. than those just mentioned. It differs \nfrom 8é, as the Lat. at and sed from autem, [cf. W. 441 \nsq. (411) ]. I. But. So related to the preceding words \nthat it serves to introduce 1. an opposition to con￾cessions; nevertheless, notwithstanding: Mt. xxiv. 6; \nMk. xiii. 20; xiv. 28; Jn. xvi. 7, 20; Acts iv. 17; vii. \n48-0 Ro. v. 14) sq55 x. 16; 1 Co. iv..4352)Co. i-.6;5 \nPhil. ii. 27 (GAN 6 Oeds ete.), ete. 2. an objection : \nJn vale 273) Ro. x. 18) sq.3 1 Copxy. 353&quot; Jas. ii, 18. \n3. an exception: Lk. xxii. 53; Ro. iv. 2; 1 Co. viii. 7; \n5 DBR 4. a restriction: Jn. xi. 42; Gal. iv. 8; Mk. \nxiv. 36. 5. an ascensive transition or gradation, \nnay rather, yea moreover: Jn. xvi. 2; 2 Co. i. 9; esp. \nwith xai added, Lk. xii. 7; xvi. 21; xxiv. 22. dAD’ ode, \nbut... not even (Germ. ja nicht einmal): Lk. xxiii. 15; \nActs xix. 2; 1 Co. iii. 2 [Rec. otre]; cf. Fritzsche op \nMk. p. 157. 6. or forms a transition to the cardinas \nmatter, especially before imperatives: Mt. ix. 18; Mk\n[continuação p. 28]\nix. 22; xvi. 7; Lk. vii. 7; In. viii. 26; xvi. 4; Acts ix. \n6 [not Rec.]; x. 20; xxvi. 16. 7. it is put ellipti￾cally: dN’ iva, i. €. GAAG TOTO yéyover, iva, Mk. xiv. 49 ; \nAfiy ait, WS 076 HR 1 Ahn sib IGE 8. after a condi￾tional or concessive protasis it signifies, at the begin￾ning of the apodosis, yet [cf. W. 442 (411)]: after kat \nei, 2 Co. xiii. 4 [RG]; Mk. xiv. 29 RGL, (2 Mace. \nviii. 15); after ei «ai, Mk. xiv. 29 [T Tr WH]; 2 Co. \niv. 16; v. 16; xi. 6; Col. ii. 5, (2 Mace. vi. 26); after \nei, 1 Co. ix. 2; Ro. vi. 5, (1 Mace. ii. 20); after édy, \n1 Co. iv. 15; after etrep, 1 Co. viii. 6 [L Tr mrg. WH br. \navn]; cf. Klotz ad Devar. ii. p. 93 8q.; Kiihner ii. \np- 827, § 535 Anm. 6. 9. after a preceding pev: Mk. \nix. 18 [T om. Tr br. pév]; Acts iv. 16; Ro. xiv. 20; \n1 Co. xiv. 17. 10. it is joined to other particles; \nadda ye [Grsb. ddAdye] (twice in the N. T.): yet at least, \n1 Co. ix. 2; yet surely (aber freilich), Lk. xxiv. 21 [LT \nTr WH add xai yea and ete.], cf. Bornemann ad loc. \nIn the more elegant Greek writers these particles are \nnot combined without the interposition of the most \nemphatic worc between them; cf. Bornemann l. c¢.; \nKlotz ad Devar. ii. pp. 15 sq. 24 sq.; Ast, Lex. Plat. i. p. \n101; [W. 444 (413)]. add # (arising from the blending \nof the two statements ovdev aAXo # and oddey aAXo, GAda) \nsave only, except: 1 Co. iii. 5 (where aAX 7H omitted \nby G L T Tr WH is spurious); Lk. xii. 51, (Sir. \nXxxvii. 12; xliv. 10); and after Ma itself, 2 Co. i. 13 \n{here Lehm. br. aX’ before #]; cf. Klotz u. s. ii. 31 sqq.; \nKiihner ii. p. 824 sq. § 535, 6; W. 442 (412); [B. 374 \n(320) ]. add ov but not, yet not: Heb. iii. 16 Gf punctu￾ated maperixpavav ; adX ov) for ‘but why do I ask? did \nnot all,’ ete.; cf. Bleek ad loc. [W. 442 (411)]. adN \novdxi will he not rather? Lk. xvii. 8. II. preceded by \na negation: but (Lat. sed, Germ. sondern) ; 1. ovk \n(Gy. GANG? Mt. xix. 1135) Mk y. 395 Jn. vit. 16) \n1 Co. i. 173; vii. 10, 19 [oddév]; 2 Co. vii. 9; 1 Tim. v. \n23 [unxére], etc. By a rhetorical construction ovk \n-.. GdAd sometimes is logically equiv. to not so much \n.as: Mk. ix. 87 (odk éué déyerat, adda Tov arooTei￾Aavra pe); Mt. x. 20; Jn. xii. 44; Acts v. 4; 1 Co. xv. \n10; 1 Th. iv. 8; by this form of speech the emphasis is \nlaid on the second member; ef. Fritzsche on Mk. Dp: \n773 sqq.; W. § 55, 8 b.; [B. 356 (306)]. od pdvov... GAA kai not only... but also: Jn. v. 18; xi. 52 [adn iva kai, etc.]; Ro. i. 32, and very often. When kai is omitted (as in the Lat. non solum... sed), the grada- tion is strengthened: Acts xix. 26 [Lchm. adds kal]; 1Jn.v.6; add\\dy\\a TOAA® paddov, Phil. ii. 12; cf. Fritzsche l. c. p. 786 sqq.; W. 498 (464); [B. 369 sq. (317)]. 2. The negation to which dddd pertains is suppressed, but can easily be supplied upon reflection [W. 442 (412)]}: Mt. xi. 7-9; Lk. vii. 24-26, (in each passage, before ddXa supply ‘ you will say you did not go out into the wilderness for this purpose’); Acts xix. 2 (we have not received the Holy Spirit, but ...); Gal. ii. 3 (they said not one word in opposition to me, but. . ») 3 2 Co. vii. 11 (where before dAdd, repeated six times by ana- phora, supply od pdvov with the accus. of the preceding \n28 adopae \nword). It is used in answers to questions having the \nforce of a negation [W. 442 (412)]: Jn. vil. 49; Acts \nxv. 11; 1 Co. x. 20. dAda iva [or GAN’ iva, cf. W. 40; \nB. 10] elliptical after a negation [W. 316 sq. (297); \n620 (576); Fritzsche on Mt. p. 840 sq.]: Jn. i. 8 (sup￾ply adda HAGev, va) ; ix. 3 (adda TUpAds eyevero [or eyer \nOn |, wa); Mk. iv. 22 (dAXa ToLodvTo eyevero, (va) eaieeelthe \nbest Mss. seem to elide the final a before nouns, but \nnot before verbs” Scrivener, Plain Introduction, etc., \np- 14; but see Dr. Gregory’s full exhibition of the facts \nin Tdf. Proleg. p. 93 sq., from which it appears that \n“elision is commonly or almost always omitted before a, \nalmost always before v, often before ¢ and n, rarely \nbefore o and , never before «; and it should be noticed \nthat this coincides with the fact that the familiar words \név, iva, Ort, ov, ws, prefer the form add”; see also WH. \nApp. p. 146. Cf. W..§ 5, 1 a.; B. p. 10.]</p></section></article>\n<article id=\"entry-thayer-0244\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλάσσω\" data-meanings=\"trocar; mudar; substituir; transformar\">ἀλλάσσω</h1><div class=\"entry-meta\">verbo em -σσω · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλλάσσω, futuro ἀλλάξω; primeiro aoristo ἤλλαξα; futuro passivo ἀλλαγήσομαι; de ἄλλος. Trocar, substituir ou fazer uma coisa ceder lugar a outra (Atos 6.14); mudar o tom de voz (Gálatas 4.20), com ressalva de Meyer; trocar uma coisa por outra (Romanos 1.23, com ἐν e dativo); transformar (1Coríntios 15.51–52; Hebreus 1.12). O autor enumera compostos.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">At 6.14; Rm 1.23; Gl 4.20; 1Co 15.51–52; Hb 1.12</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">Drdcow: fut. addrAd€o; 1 aor. 7#AdAa~a; 2 fut. pass. \nddAaynoopa; (dAdos); [fr. Aeschyl. down]; to change: \nto cause one thing to cease and another to take its \nplace, ra ny, Acts vi. 14; tiv parvny to vary the voice, \ni.e. to speak in a different manner according to the \ndifferent conditions of minds, to adapt the matter and \nform of discourse to mental moods, to treat them now \nseverely, now gently, Gal. iv. 20 [but see Meyer ad \nloc.]. to exchange one thing for another: ri é&amp;v tum, \nRo. i. 23 (2 V7 Ps. ev. (evi.) 20; the Greeks say da￾Adooew ri twos [cf. W. 206 (194), 388 (363); Vaughan \non Rom.1|.¢.]). to transform: 1 Co. xv. 51 sq.; Heb. i. \n12. [Comp.: dm-, dv-, kat-, amo-Kat-, weT-, Tvy-addaooe. | *</p></section></article>\n<article id=\"entry-thayer-0245\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλαχόθεν\" data-meanings=\"por outro lugar; de outra direção\">ἀλλαχόθεν</h1><div class=\"entry-meta\">advérbio · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλλαχόθεν, advérbio: de outro lugar, por outro caminho ou entrada; João 10.1. Thayer equipara à forma ἄλλοθεν, preferida por determinados gramáticos, e cita Antifonte, Thomas Magister e Moeris.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Jo 10.1</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">ddaxsbev, adv., from another place: Jn. x. 1 (i. q. \n@dobev [which the grammarians prefer, Thom. Mag. \ned. Ritschl p. 10, 13; Moeris ed: Piers. p.11]; ef. \néxaotaxdbev, mavtaxdbev). [(Antiph., al.)]*</p></section></article>\n<article id=\"entry-thayer-0246\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλαχοῦ\" data-meanings=\"em outro lugar; alhures\">ἀλλαχοῦ</h1><div class=\"entry-meta\">advérbio · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλλαχοῦ, advérbio, equivalente a ἄλλοθι: em outro lugar, alhures, Marcos 1.38 segundo certas edições de Tischendorf, Tregelles e Westcott–Hort. Thayer remete a Bornemann e aos gramáticos mencionados na entrada precedente.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mc 1.38</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">®dAaxod, adv., i. gq. dAoM, elsewhere, in another place: \nMk. i. 38 (T Tr txt. WH Tr mrg. br.). Cf. Borne￾mann in the Stud. u. Krit. for 1843, p. 127 sq. [Soph., \nXen., al.; see Thom. M. and Moer. as in the preced. \nword. | *</p></section></article>\n<article id=\"entry-thayer-0247\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλληγορέω\" data-meanings=\"falar alegoricamente; interpretar figuradamente\">ἀλληγορέω</h1><div class=\"entry-meta\">verbo em -έω · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλληγορέω, -ῶ: dizer uma coisa pelas palavras e indicar outra pelo sentido, «falar em alegoria» (Quintiliano, *Institutio oratoria* 8.6.44). Gálatas 4.24, em interpretação figurada. Compara Fílon, Josefo, Plutarco e gramáticos.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Gl 4.24</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dAAnyopew, -&amp;: [pres. pass. ptep. adAnyopotpevos ]; i. e. \n@\\Xo péev ayopeta, do b€ vow, “aliud verbis, aliud \nsensu ostendo ” (Quint. instt. 8, 6, 44), to speak alle￾gorically or in a figure: Gal. iv. 24. (Philo, Joseph., \nPlut., and gram. writ.; [ef. Mey. on Gal. l. ¢.].)*</p></section></article>\n<article id=\"entry-thayer-0248\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλληλουϊά\" data-meanings=\"aleluia! louvai ao Senhor!\">ἁλληλουϊά</h1><div class=\"entry-meta\">interjeição hebraica transcrita; indeclinável · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἁλληλουϊά, com grafias variantes assinaladas por Westcott–Hort, do hebraico הַלְלוּ־יָהּ: «louvai ao SENHOR» ou «aleluia». Apocalipse 19.1,3–4,6; ocorre amplamente nos Salmos da Septuaginta e também em Tobias e 3Macabeus.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Ap 19.1,3–4,6</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">éAAnAovia, [ WH. ‘AAA. and -a; see Intr. § 408], Hebr. \nW197, praise ye the Lord, Hallelujah: Rev. xix. 1, 3 sq. \n6. [Sept. Pss. passim; Tob. xiii. 18; 3 Mace. vii. 13.]*</p></section></article>\n<article id=\"entry-thayer-0249\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλήλων\" data-meanings=\"uns aos outros; mutuamente\">ἀλλήλων</h1><div class=\"entry-meta\">pronome recíproco; apenas casos oblíquos · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλλήλων, genitivo plural, sem nominativo possível; dativos ἀλλήλοις, ἀλλήλαις, ἀλλήλοις; acusativos ἀλλήλους, ἀλλήλας, ἄλληλα. Pronome recíproco: «um ao outro», «uns aos outros», «mutuamente». Exemplos Mateus 24.10; João 13.35; Atos 28.25; Romanos 1.12; Tiago 5.16; Apocalipse 6.4. Usado desde Homero.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Mt 24.10; Jo 13.35; At 28.25; Rm 1.12; Tg 5.16; Ap 6.4</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">GAAfAwv, gen. plur. [no nom. being possible]; dat. \n-OlS, -als, -Ols; ACC. -oUS, -as, -a, One another ; reciprocally, \nmutually: Mt. xxiv. 10; Jn. xiii. 35; Acts xxviii. 25; \nRo. i. 12; Jas. v. 16; Rev. vi. 4, and often. [Fr. Hom. \ndown. ]</p></section></article>\n<article id=\"entry-thayer-0250\" class=\"entry-card\" data-dictionary=\"grego\" data-thayer-page=\"28\" data-thayer-pdf-leaf=\"52\" data-thayer-column=\"esquerda\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλογενής\" data-meanings=\"estrangeiro; de outra raça ou nação\">ἀλλογενής</h1><div class=\"entry-meta\">adjetivo de duas terminações, -ές · Thayer, p. 28, esquerda</div></div><div class=\"source-tag\">THAYER</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução portuguesa de trabalho</div><p class=\"entry-text\">ἀλλογενής, -ές, de ἄλλος e γένος: de outra raça, povo ou nacionalidade, estrangeiro. Lucas 17.18. Frequente na Septuaginta (Gênesis 17.27; Êxodo 12.43), mas não encontrado nos escritores profanos consultados por Thayer.</p></section><section class=\"entry-section\"><div class=\"section-title\">Referências</div><p class=\"entry-text\">Lc 17.18</p></section><section class=\"entry-section\"><div class=\"section-title\">Fac-símile e OCR auxiliar</div><p class=\"entry-text\">Thayer, <em>A Greek-English Lexicon of the New Testament</em>, páginas impressas 28, folhas PDF 52, coluna esquerda. OCR bruto originado nas fotografias e sujeito a erros. Prevalece a fonte impressa. Tradução de trabalho, sem certificação de integralidade.</p><p class=\"entry-text\" style=\"white-space:pre-wrap\">dAXoyevtjs, -€s, (GAXos and yévos), sprung from another \nrace, a foreigner, alien: Lk. xvii. 18. (In Sept. [Gen. \nxvii. 27; Ex. xii. 43, etc.], but nowhere in prof. writ.)*</p></section></article>\n";
